import {STAGES,money,total,TODAY} from './model.mjs';
import {summary,paymentReport,STAGE_INFO,NOTICE_LABELS,notificationState} from './workflow.mjs';

export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon=n=>`<i data-lucide="${n}"></i>`;
const caseUnit=n=>n%100>=11&&n%100<=14?'дел':n%10===1?'дело':n%10>=2&&n%10<=4?'дела':'дел';
export function overviewRows(rows,{company='',building='',houseStatus=''}={}){
  return rows.filter(r=>(!company||r.company===company)&&(!building||r.building===building)&&(!houseStatus||(r.houseStatus||'unknown')===houseStatus));
}
export function overviewFilters(rows,scope){
  const options=(items,current,all)=>`<option value="">${all}</option>${items.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x)}</option>`).join('')}`;
  return `<div class="overview-filters"><label>Управляющая компания<select data-overview-filter="company">${options([...new Set(rows.map(r=>r.company))],scope.company,'Все УК')}</select></label><label>Дом<select data-overview-filter="building">${options([...new Set(overviewRows(rows,{company:scope.company}).map(r=>r.building))],scope.building,'Все дома')}</select></label><label>Статус дома<select data-overview-filter="houseStatus"><option value="">Все статусы</option><option value="active" ${scope.houseStatus==='active'?'selected':''}>В управлении</option><option value="departed" ${scope.houseStatus==='departed'?'selected':''}>Выбывшие дома</option><option value="unknown" ${scope.houseStatus==='unknown'?'selected':''}>Статус не загружен</option></select></label></div>`;
}
export function overview(allRows,from,to,scope={}){
  const rows=overviewRows(allRows,scope);
  const s=summary(rows),p=paymentReport(rows,'0001-01-01',TODAY);
  const dates=[...new Set(rows.map(r=>r.asOf).filter(Boolean))].sort(),periods=[...new Set(rows.map(r=>r.billing?.lines.map(x=>x.month).sort().at(-1)).filter(Boolean))].sort();
  return `${overviewFilters(allRows,scope)}<p class="data-freshness">${dates.length?`Остатки на ${esc(dates[0])}${dates.length>1?' — '+esc(dates.at(-1)):''}`:'Дата остатков не загружена'}${periods.length?` · Последний расчётный месяц: ${esc(periods.join(', '))}`:''} · Учебные данные</p><section class="overview-totals" aria-label="Текущий остаток">
    <div><span>Основной долг сейчас</span><strong>${money(rows.reduce((sum,r)=>sum+r.principal,0))}</strong><small>Пени: ${money(rows.reduce((sum,r)=>sum+r.penalty,0))} · пошлина: ${money(rows.reduce((sum,r)=>sum+r.fee,0))}</small><small>Общая задолженность: ${money(s.amount)}</small></div>
    <div><span>Поступило за всё время</span><strong>${money(p.all.amount)}</strong><small>Основной долг: ${money(p.all.principal)}</small><small>Пени: ${money(p.all.penalty)} · пошлина: ${money(p.all.fee)}</small><small>Вся загруженная история оплат до ${esc(TODAY)}</small></div>
    <div><span>Лицевых счетов с долгом</span><strong>${s.accounts}</strong><small>В ${s.premises} помещениях</small></div>
  </section>
  ${rows.some(r=>r.reviewTask?.status==='open')?`<button class="review-counter" data-queue="waiting"><strong>${rows.filter(r=>r.reviewTask?.status==='open').length}</strong> На уточнении у бухгалтера ${icon('arrow-up-right')}</button>`:''}
  <div class="section-head"><h2>Текущие дела</h2><button class="icon-button" data-action="stageHelp" title="Что означают этапы" aria-label="Что означают этапы">${icon('circle-help')}</button></div>
  <div class="stage-list">${s.stages.filter(x=>x.stage!=='Суд: уточнить'||x.count>0).map(x=>`<button class="stage-tile" data-stage-link="${esc(x.stage)}"><span>${esc(STAGE_INFO[x.stage].title)}</span><strong>${x.caseCount}</strong><small>${x.stage==='Без дела'?'ЛС с долгом вне дел':caseUnit(x.caseCount)} · ${money(x.amount)}</small>${icon('arrow-up-right')}</button>`).join('')}</div>
  <small class="definition">В выборке ${rows.length} ЛС, включая ${rows.filter(r=>total(r)===0).length} без задолженности. Один ЛС может иметь несколько дел. Долг вне дел показан отдельно. ${rows.some(r=>r.caseBalanceConflict)?'Суммы по делам требуют уточнения.':''}</small><div class="overview-section"><div class="section-head"><h2>Уведомления</h2><button class="button small" data-queue="notify">${icon('send')} Подготовить уведомления</button></div>
  <div class="notification-strip">${Object.entries(NOTICE_LABELS).map(([key,label])=>`<button data-notice-link="${key}"><strong>${s.notices[key]}</strong><span>${label}</span></button>`).join('')}</div>
  <small class="definition">Только ЛС с долгом. Подготовленный документ не означает доставку или ознакомление жителя.</small></div>
  `;
}
export function stageGuide(){return `<p class="form-note">Рабочие этапы, не обязательная цепочка. Соглашение может не заключаться; после приказа не всегда нужен иск. Переход подтверждает сотрудник по документам.</p><dl class="stage-guide">${STAGES.slice(1).map(s=>`<div><dt>${esc(STAGE_INFO[s].title)}</dt><dd>${esc(STAGE_INFO[s].meaning)}<small>Следующий шаг: ${esc(STAGE_INFO[s].next)}</small></dd></div>`).join('')}</dl><p class="form-note">«Приказ» и «Иск» здесь разделены по виду судебной работы. Основания и сроки для конкретного дела определяет юрист. Это концепция интерфейса, не инструкция по судебному взысканию.</p><a href="https://www.vsrf.ru/documents/own/16145/" target="_blank" rel="noopener">Разъяснения Верховного Суда, пункт 5</a>`;}
export function stageContext(stage){const x=STAGE_INFO[stage];return x?`<div class="stage-context"><div><strong>${esc(x.title)}</strong><p>${esc(x.next)}</p></div><button class="icon-button" data-action="stageHelp" title="Смысл этапов" aria-label="Смысл этапов">${icon('circle-help')}</button></div>`:'';}
export function receiptPages(r){return `<div class="receipt-preview"><section class="paper"><small>ЛИСТ 1 · ДЕМО-КВИТАНЦИЯ</small><h3>${esc(r.company)}</h3><p>${esc(r.building)}, кв. ${esc(r.flat)} · ЛС ${esc(r.account)}</p><dl><div><dt>Основной долг</dt><dd>${money(r.principal)}</dd></div><div><dt>Пени</dt><dd>${money(r.penalty)}</dd></div><div><dt>Госпошлина к возмещению</dt><dd>${money(r.fee)}</dd></div><div><dt>Остаток задолженности</dt><dd><strong>${money(total(r))}</strong></dd></div></dl><small>Данные на ${esc(r.asOf)}. Текущие начисления в этот пример не включены.</small></section><section class="paper"><small>ЛИСТ 2 · ДЕМО-ПРЕТЕНЗИЯ</small><h3>Претензия об оплате задолженности</h3><p>${esc(r.building)}, кв. ${esc(r.flat)} · ЛС ${esc(r.account)}</p><p>На ${esc(r.asOf)} задолженность за ${esc(r.period)}: ${money(total(r))}. За услуги ${money(r.principal)}, пени ${money(r.penalty)}, госпошлина ${money(r.fee)}.</p><p>Просим погасить задолженность. Если оплата уже произведена или Вы не согласны с суммой, сообщите об этом управляющей компании.</p><p>Представитель: ____________________</p><hr><h4>Извещение об оплате</h4><p>${esc(r.company)} · ЛС ${esc(r.account)}<br>К оплате: <strong>${money(total(r))}</strong></p><small>Без действующих реквизитов, QR-кода и подписи.</small><hr><h4>Отметка о вручении</h4><p>Документ на сумму ${money(total(r))} получен.<br>Дата __________ ФИО __________ Подпись __________</p><small>Заполняется при фактическом вручении. Учебная адаптация предоставленного образца; правовые основания и срок ответа проверяет юрист.</small></section></div>`;}
export function noticeBadge(r){return `<small class="notice-state">${esc(NOTICE_LABELS[notificationState(r)])}</small>`;}
